diff --git a/buildSrc/src/main/java/org/opensearch/gradle/RepositoriesSetupPlugin.java b/buildSrc/src/main/java/org/opensearch/gradle/RepositoriesSetupPlugin.java
index f8387d8..d4e5678 100644
--- a/buildSrc/src/main/java/org/opensearch/gradle/RepositoriesSetupPlugin.java
+++ b/buildSrc/src/main/java/org/opensearch/gradle/RepositoriesSetupPlugin.java
@@ -18,6 +18,13 @@ public class RepositoriesSetupPlugin implements Plugin<Project> {
     public void apply(Project project) {
         RepositoryHandler repos = project.getRepositories();
         repos.mavenLocal();
+
+        // OpenSearch snapshot repository — mirrors the existing Lucene snapshot repo
+        // at ci.opensearch.org/ci/dbc/snapshots/lucene/ per opensearch-project/opensearch#1234
+        repos.maven(repo -> {
+            repo.setName("opensearch-snapshots");
+            repo.setUrl("https://ci.opensearch.org/ci/dbc/snapshots/opensearch/");
+        });
+
         repos.mavenCentral();
